    SceneState layers;layers.width=layers.height=128;layers.floor=112;layers.origin_x=layers.origin_y=64;layers.assets=initial.assets;for(int i=0;i<2;++i){SceneLane l;l.name=i?"Green":"Red";SceneFrame f;f.pieces={scene_sprite_reference(i?*b:*a,i,i?solid_b:solid_a)};l.frames={f};layers.lanes.push_back(l);}SceneProject stack(layers);auto red=stack.state.lanes[0].id,green=stack.state.lanes[1].id;
    auto pixel=[&](bool expect_red){CHECK(stack.export_png((root/"layers.png").u8string(),0,source,error));auto bytes=read(root/"layers.png");int w=0,h=0,c=0;auto image=stbi_load_from_memory((const unsigned char *)bytes.data(),(int)bytes.size(),&w,&h,&c,4);CHECK(image&&w==128&&h==128);if(image){auto px=image+((size_t)64*w+64)*4;CHECK(px[0]==(expect_red?255:0)&&px[1]==(expect_red?0:255)&&px[2]==0);stbi_image_free(image);}};
    pixel(false);CHECK(stack.move_actor(red,1,error)==1);pixel(true);stack.undo();pixel(false);stack.redo();pixel(true);stack.begin("Depth");for(auto &l:stack.state.lanes)l.frames[0].z=l.id==green?5:0;stack.commit();pixel(false);CHECK(stack.move_actor(red,-1,error)==0);pixel(false);
    for(auto id:{0ull,999999ull}){snapshot=state(p.state);bool undo=p.can_undo(),redo=p.can_redo();CHECK(p.duplicate_actor(id,error)==-1&&p.move_actor(id,1,error)==-1&&state(p.state)==snapshot&&p.can_undo()==undo&&p.can_redo()==redo);}snapshot=state(p.state);CHECK(p.move_actor(10,0,error)==-1&&state(p.state)==snapshot);p.begin("Pending");CHECK(p.duplicate_actor(10,error)==-1&&p.move_actor(10,1,error)==-1&&p.transaction_open());p.cancel();CHECK(state(p.state)==snapshot);
    auto full_state=initial;while(full_state.lanes.size()<32){auto l=full_state.lanes[0];l.id=0;for(auto &f:l.frames)f.id=0;full_state.lanes.push_back(l);}SceneProject full(full_state);snapshot=state(full.state);CHECK(full.duplicate_actor(10,error)==-1&&state(full.state)==snapshot&&!full.can_undo());
    auto late=initial;late.lanes[0].delay=100000;SceneProject delayed(late);snapshot=state(delayed.state);CHECK(delayed.duplicate_actor(10,error)==-1&&state(delayed.state)==snapshot);
    auto exhausted=initial;exhausted.lanes[0].frames[0].id=INT_MAX-2;SceneProject max(exhausted);CHECK(max.duplicate_actor(10,error)==-1&&!max.can_undo());exhausted.lanes[0].frames[0].id=INT_MAX-4;SceneProject last(exhausted);CHECK(last.duplicate_actor(10,error)==2&&last.state.lanes[2].frames.back().id==INT_MAX);last.undo();CHECK(last.duplicate_actor(10,error)==-1&&last.can_redo());
    auto names=initial;names.lanes[1].name=std::string(119,'X')+u8"日é";SceneProject unicode(names);CHECK(unicode.duplicate_actor(10,error)==2&&unicode.state.lanes[2].name==std::string(119,'X')+" (copy)");
    // Limits are checked before building a large duplicate.
    SceneState caps;caps.assets=initial.assets;SceneLane massive;SceneFrame repeated;repeated.pieces.assign(32,scene_sprite_reference(*a,0,0));massive.frames.assign(1025,repeated);caps.lanes={massive};SceneProject references(caps);snapshot=state(references.state);CHECK(references.duplicate_actor(references.state.lanes[0].id,error)==-1&&state(references.state)==snapshot&&!references.can_undo());
    SceneState frame_cap;frame_cap.assets=initial.assets;repeated.pieces.resize(1);massive.frames.assign(4096,repeated);frame_cap.lanes={massive,massive};SceneProject lots(frame_cap);snapshot=state(lots.state);CHECK(lots.duplicate_actor(lots.state.lanes[0].id,error)==-1&&state(lots.state)==snapshot&&!lots.can_undo());
    for(int op=0;op<3;++op){int failed=0,succeeded=0;for(int n=0;n<1500;++n){SceneProject target(initial);target.begin("Move");target.state.lanes[1].x++;target.commit();target.undo();snapshot=state(target.state);int result=-1;fail_after=n;try{result=op?target.move_actor(10,op==1?1:-1,error):target.duplicate_actor(10,error);}catch(const std::bad_alloc &){}fail_after=-1;if(result<0){++failed;CHECK(state(target.state)==snapshot&&!target.can_undo()&&target.can_redo()&&target.dirty());CHECK(target.duplicate_actor(10,error)==2&&target.state.lanes[2].id==22);}else{++succeeded;CHECK(!target.can_redo());target.undo();CHECK(state(target.state)==snapshot);}}CHECK(failed>20&&succeeded>0);}
    CHECK(a->generation()==ga&&b->generation()==gb&&!a->dirty()&&!b->dirty()&&read(root/"a.IMG")==a_bytes&&read(root/"b.IMG")==b_bytes&&g_doc==nullptr);CHECK(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent));if(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent))fs::remove_all(root);std::cout<<"Actor rows: "<<failures<<" failure(s)\n";return failures?1:0;
